-- Regenerate lua/tracker/data/emoji.lua from GitHub's gemoji:
--   curl -L -o emoji.json https://raw.githubusercontent.com/github/gemoji/master/db/emoji.json
--   nvim -l scripts/gen_emoji.lua emoji.json lua/tracker/data/emoji.lua
-- gemoji's MIT license travels with the data: lua/tracker/data/LICENSE-gemoji.
local src, dst = arg[1], arg[2]
local list = vim.json.decode(table.concat(vim.fn.readfile(src), "\n"))
local out = {
  "-- Generated by scripts/gen_emoji.lua from github/gemoji db/emoji.json",
  "-- (MIT License, Copyright (c) 2019 GitHub, Inc. — full text in",
  "-- lua/tracker/data/LICENSE-gemoji). Do not edit by hand.",
  "-- Each entry: { glyph, name, more names… } (gemoji aliases, then the",
  "-- Unicode description as a name: \"grinning_face\").",
  "return {",
}
for _, e in ipairs(list) do
  local names, seen = {}, {}
  local function add(n)
    n = n:lower():gsub("[^%w_+%-]+", "_"):gsub("^_+", ""):gsub("_+$", "")
    if n ~= "" and not seen[n] then
      seen[n] = true
      table.insert(names, n)
    end
  end
  for _, a in ipairs(e.aliases or {}) do add(a) end
  add(e.description or "")
  local parts = { ("%q"):format(e.emoji) }
  for _, n in ipairs(names) do table.insert(parts, ("%q"):format(n)) end
  table.insert(out, "  { " .. table.concat(parts, ", ") .. " },")
end
table.insert(out, "}")
vim.fn.writefile(out, dst)
print(("%d emoji → %s"):format(#list, dst))
